import {useSlots} from '@primer/react/experimental'
import {Stack} from '@primer/react'
import styles from './styles.module.css'

export type TopNavProps = React.PropsWithChildren<{}>

function TopNavComponent(props: TopNavProps) {
  const [{left, right}, rest] = useSlots(props.children, {
    left: Left,
    right: Right,
  })

  return (
    <Stack as="header" className={styles.appHeader} role="banner" aria-label="Global Navigation Menu">
      <Stack direction="horizontal" align="center" justify="center">
        {left}
        {right}
      </Stack>
      {rest}
    </Stack>
  )
}

function Left(props: React.PropsWithChildren<{}>) {
  return (
    <Stack data-test-id="top-nav-left" direction="horizontal" className="flex-1" gap="normal" padding="normal">
      {props.children}
    </Stack>
  )
}

function Right(props: React.PropsWithChildren<{}>) {
  return (
    <Stack data-test-id="top-nav-right" direction="horizontal" align="center" gap="condensed" padding="normal">
      {props.children}
    </Stack>
  )
}

/**
 * The TopNav component lays the structure for the top navigation bar within product
 * Use the `TopNav.Left` and `TopNav.Right` slots to define the content on the left and right sides of the navigation bar.
 * Any additional children will be shown below the initial bar (such as Local Navigation)
 */
export const TopNav = Object.assign(TopNavComponent, {Left, Right})

try{ TopNavComponent.displayName ||= 'TopNavComponent' } catch {}
try{ Left.displayName ||= 'Left' } catch {}
try{ Right.displayName ||= 'Right' } catch {}
try{ TopNav.displayName ||= 'TopNav' } catch {}