import {InternallyAnchoredGlobalNavMenu, type InternallyAnchoredGlobalNavMenuProps} from '../menu/GlobalNavMenu'
import {GitPullRequestIcon, IssueOpenedIcon} from '@primer/octicons-react'
import {GlobalNavUserMenu, type GlobalNavUserMenuProps} from '../user-menu/GlobalNavUserMenu'
import {ContextualNavigation} from '../local-navigation/ContextualNavigation'
import {TopNav} from '../primitives/TopNav'
import {HeaderLogo, type HeaderLogoProps} from './items/HeaderLogo'
import {NavLinkItem} from '../primitives/NavItemLink'
import {NotificationItem, type NotificationItemProps} from './items/Notification'
import {NavCrumbs} from './items/NavCrumbs'

export interface GlobalNavBarProps {
  /** Props to control the left navigation menu */
  navMenu: InternallyAnchoredGlobalNavMenuProps

  /** Props to control the right, user menu */
  userMenu: GlobalNavUserMenuProps

  /** Information about the user's notifications */
  notifications?: NotificationItemProps

  /** Props for the main header logo */
  headerLogo?: HeaderLogoProps

  // TODO: Options from rails version to consider:
  // - hide_menu_and_logo_on_desktop
  // - rich_content_enabled (overlaps w/ left-nav)
  // - hide_search
  // - blackbird_enabled
}

export function GlobalNavBar(props: GlobalNavBarProps) {
  return (
    <TopNav>
      <TopNav.Left>
        <InternallyAnchoredGlobalNavMenu {...props.navMenu} />
        <HeaderLogo {...props.headerLogo} />
        <NavCrumbs />
      </TopNav.Left>

      <TopNav.Right>
        <NavLinkItem href="/issues" aria-label="Your Issues" icon={IssueOpenedIcon} analyticsKey="ISSUES_HEADER" />
        <NavLinkItem
          href="/pulls"
          aria-label="Your Pull Requests"
          icon={GitPullRequestIcon}
          analyticsKey="PULL_REQUESTS_HEADER"
        />
        <NotificationItem />
        <GlobalNavUserMenu {...props.userMenu} />
      </TopNav.Right>

      <ContextualNavigation />
    </TopNav>
  )
}

try{ GlobalNavBar.displayName ||= 'GlobalNavBar' } catch {}