import {IconButton} from '@primer/react'
import {GlobalUserNavDrawer, type GlobalUserNavDrawerProps} from '@github-ui/global-user-nav-drawer'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useState} from 'react'
import {useGlobalNavAnalytics} from '../utils/analytics'

export type GlobalNavUserMenuProps = GlobalUserNavDrawerProps

export function GlobalNavUserMenu(props: GlobalUserNavDrawerProps) {
  const [open, setOpen] = useState(false)
  const {sendItemClick} = useGlobalNavAnalytics()

  // TODO: Move this button and state into the <GlobalUserNavDrawer />
  // Will need some updates to work with the new reductive nav

  return (
    <>
      <IconButton
        variant="invisible"
        icon={() => <GitHubAvatar size={32} alt={props.owner.name ?? 'User avatar'} src={props.owner?.avatarUrl} />}
        aria-label="Open user navigation menu"
        aria-haspopup="menu"
        onClick={() => {
          setOpen(!open)
          sendItemClick(`USER_NAV_MENU_TOGGLE`)
        }}
      />
      {open && <GlobalUserNavDrawer {...props} onClose={() => setOpen(false)} />}
    </>
  )
}

try{ GlobalNavUserMenu.displayName ||= 'GlobalNavUserMenu' } catch {}