import {MarkGithubIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import styles from './styles.module.css'
import {useGlobalNavAnalytics} from '../../utils/analytics'

export interface HeaderLogoProps {
  href?: string
  'aria-label'?: string
  hotkey?: string
}

export function HeaderLogo(props: HeaderLogoProps) {
  // This differs from the default `category` but matches what's in the rails app today
  const {sendItemClick} = useGlobalNavAnalytics('Header')

  return (
    <IconButton
      as="a"
      href="/"
      variant="invisible"
      className={styles.appHeaderHome}
      icon={() => <MarkGithubIcon size="medium" />}
      data-hotkey={props.hotkey}
      keybindingHint={props.hotkey}
      aria-label="Dashboard"
      onClick={() => {
        sendItemClick('go to dashboard')
      }}
      {...props}
    />
  )
}

try{ HeaderLogo.displayName ||= 'HeaderLogo' } catch {}